<script setup lang="ts">
import { computed } from 'vue'
import { ChevronDown,ChevronRight,Package,ShoppingCart,Link2,Boxes } from 'lucide-vue-next'
import type { InboundStockGroup } from '@/api/receipt-notices'
import StockCopy from './StockCopy.vue'
import { vPickingNameTooltip } from '@/directives/picking-name-tooltip'
const props=defineProps<{group:InboundStockGroup;expanded:boolean;busy:boolean}>()
defineEmits<{toggle:[]}>()
const type=computed(()=>props.group.type==='full_payment'?'全款备货':props.group.type==='deposit'?'押金备货':'备货')
const remaining=computed(()=>props.group.products.filter(p=>p.unassignedQuantity===null||p.unassignedQuantity>0))
const qty=(v:number|null)=>v==null?'—':v.toLocaleString('zh-CN',{maximumFractionDigits:8})
const packageStatus=(values:(string|null)[])=>values.every(v=>v==='30')?'已完成':values.some(v=>v==='10')?'入库中':'待入库'
</script>
<template>
 <div class="stock-group">
  <div class="root-header"><button class="expand" :disabled="busy" :aria-expanded="expanded" :aria-label="`展开备货订单 ${group.number}`" @click="$emit('toggle')"><ChevronDown v-if="expanded" :size="16"/><ChevronRight v-else :size="16"/></button><span class="type">{{type}}</span><StockCopy :value="group.number"/><div class="root-counts"><span>采购单 <b>{{group.purchases.length}}</b></span><span>包裹 <b>{{group.packages.length}}</b></span><span>关联履约 <b>{{group.orders.length}}</b></span><span>未关联 <b>{{qty(group.totals.unassignedQuantity)}}</b> 件</span></div></div>
  <div v-if="expanded" class="group-content">
   <section class="purchase-tree"><div class="branch-title"><ShoppingCart :size="15"/><strong>关联采购订单</strong><span>采购数量合计 {{qty(group.totals.purchaseQuantity)}} 件</span></div><div class="purchase-branches"><div v-for="p in group.purchases" :key="p.id" class="purchase-node"><StockCopy :value="p.number"/><span class="muted">{{p.status||'—'}} · {{p.paymentStatus||'—'}}</span><span>{{qty(p.quantity)}} 件</span><small>{{group.packages.filter(pkg=>pkg.purchaseIds.includes(p.id)).length}} 个关联包裹</small></div><span v-if="!group.purchases.length" class="muted">暂无关联采购订单</span></div></section>
   <div class="linked-lists">
    <section class="list-card"><header><Package :size="16"/><h3>包裹清单</h3><span>{{group.packages.length}} 个</span></header><div class="list-body"><div v-for="p in group.packages" :key="p.id" class="list-row"><div class="row-heading"><StockCopy v-if="p.trackingNumber" :value="p.trackingNumber"/><span v-else>未提供快递单号</span><span class="muted">{{packageStatus(p.statuses)}}</span></div><small>{{p.carrier||'—'}}</small><small v-for="n in p.noticeNumbers" :key="n">{{n}}</small></div><div v-if="!group.packages.length" class="empty">暂无包裹</div></div></section>
    <section class="list-card"><header><Link2 :size="16"/><h3>耗用履约订单</h3><span>{{group.orders.length}} 笔</span></header><div class="list-body"><div v-for="o in group.orders" :key="o.id" class="list-row"><div class="row-heading"><StockCopy :value="o.number"/><span>{{qty(o.reservedQuantity+o.usedQuantity)}} 件</span></div><small>{{o.customerName||'—'}} · 预占 {{qty(o.reservedQuantity)}} / 已耗用 {{qty(o.usedQuantity)}}</small><small>{{o.skus.join('、')}}</small></div><div v-if="!group.orders.length" class="empty">本权限范围暂无关联履约订单</div></div></section>
    <section class="list-card"><header><Boxes :size="16"/><h3>未关联履约商品</h3><span>{{qty(group.totals.unassignedQuantity)}} 件</span></header><div class="list-body"><div v-for="p in remaining" :key="p.sku" class="list-row"><div class="row-heading"><span v-picking-name-tooltip="p.name||''" class="product-name">{{p.name||'—'}}</span><strong>{{qty(p.unassignedQuantity)}} 件</strong></div><small>{{p.sku}}</small><small>备货 {{qty(p.quantity)}} · 预占 {{qty(p.reservedQuantity)}} · 已耗用 {{qty(p.usedQuantity)}}</small></div><div v-if="!remaining.length" class="empty">备货商品已全部关联履约订单</div></div></section>
   </div>
   <details class="goods-summary"><summary>备货商品汇总 · {{group.products.length}} 个 SKU · {{qty(group.totals.stockQuantity)}} 件</summary><table><thead><tr><th>商品</th><th>SKU</th><th>备货数量</th><th>预占</th><th>已耗用</th><th>未关联</th></tr></thead><tbody><tr v-for="p in group.products" :key="p.sku"><td><span class="product-name" v-picking-name-tooltip="p.name||''">{{p.name||'—'}}</span></td><td>{{p.sku}}</td><td>{{qty(p.quantity)}}</td><td>{{qty(p.reservedQuantity)}}</td><td>{{qty(p.usedQuantity)}}</td><td>{{qty(p.unassignedQuantity)}}</td></tr></tbody></table></details>
   <p class="scope-note">三组清单按备货订单关联；未关联数量＝备货商品数量－预占－已耗用。采购数量按本单关联采购分录汇总，包裹不分摊商品或耗用数量。</p>
  </div>
 </div>
</template>
